package expo.modules.linking

import android.content.Context
import expo.modules.core.interfaces.ApplicationLifecycleListener
import expo.modules.core.interfaces.InternalModule
import expo.modules.core.interfaces.Package
import expo.modules.core.interfaces.ReactActivityHandler
import expo.modules.core.interfaces.ReactActivityLifecycleListener
import expo.modules.core.interfaces.ReactNativeHostHandler
import expo.modules.core.interfaces.SingletonModule

class ExpoLinkingPackage : Package {
  override fun createReactActivityLifecycleListeners(activityContext: Context?): List<ReactActivityLifecycleListener> {
    return listOf(LinkingReactActivityLifecycleListener())
  }
  
  // Explicitly implement all interface methods to fix AbstractMethodError with expo-modules-core@3.0.29
  // These methods have default implementations in Java but need explicit overrides in Kotlin
  // when compiled against older expo-modules-core versions
  override fun createInternalModules(context: Context): List<InternalModule> {
    return emptyList()
  }
  
  override fun createSingletonModules(context: Context): List<SingletonModule> {
    return emptyList()
  }
  
  override fun createApplicationLifecycleListeners(context: Context): List<ApplicationLifecycleListener> {
    return emptyList()
  }
  
  override fun createReactNativeHostHandlers(context: Context): List<ReactNativeHostHandler> {
    return emptyList()
  }
  
  override fun createReactActivityHandlers(activityContext: Context): List<ReactActivityHandler> {
    return emptyList()
  }
}
